export const DEFAULT_SYSTEM_INSTRUCTION = `You are Pr0mptim1zer, an expert prompt engineer and LLM architect. 
Your goal is to rewrite user inputs into highly optimized prompts specifically tailored for a target Large Language Model.

1. Analyze the user's intent.
2. Identify the target model selected.
3. Rewrite the prompt using best practices for that specific model (e.g., Use XML tags for Claude, Chain of Thought for Reasoning models, Clear markdown structure for Gemini).
4. Do NOT answer the user's prompt. ONLY rewrite it.
5. Provide a very brief (one sentence) explanation of the key change you made.

Output format should be JSON:
{
  "optimizedPrompt": "The full rewritten prompt text...",
  "explanation": "Added XML tags for better separation of concern."
}`;

import { GoogleGenAI, Type } from "@google/genai";
import { OptimizationResponse, TargetModelId } from '../types';
import { DEFAULT_SYSTEM_INSTRUCTION } from '../constants';

// We use Gemini to optimize the prompts for *other* models as well, 
// because Gemini 1.5 Pro is excellent at following complex meta-instructions.
const MODEL_NAME = 'gemini-2.5-flash-latest'; 

export const optimizePrompt = async (
  originalPrompt: string,
  targetModelId: TargetModelId
): Promise<OptimizationResponse> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please set the API_KEY environment variable.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Target Model: ${targetModelId}
    User Draft:
    """
    ${originalPrompt}
    """
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-09-2025", // Using the latest preview for best instruction following
      contents: prompt,
      config: {
        systemInstruction: DEFAULT_SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            optimizedPrompt: {
              type: Type.STRING,
              description: "The fully rewritten, optimized prompt ready to be pasted."
            },
            explanation: {
              type: Type.STRING,
              description: "A very brief explanation of the optimization technique used."
            }
          },
          required: ["optimizedPrompt", "explanation"]
        }
      }
    });

    const responseText = response.text;
    if (!responseText) {
      throw new Error("No response received from Gemini.");
    }

    const data = JSON.parse(responseText) as OptimizationResponse;
    return data;

  } catch (error) {
    console.error("Optimization failed:", error);
    throw new Error("Failed to optimize prompt. Please try again.");
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown, Check, Zap } from 'lucide-react';
import { TargetModel, TargetModelId } from '../types';
import { TARGET_MODELS } from '../constants';

interface ModelSelectorProps {
  selectedModel: TargetModel;
  onSelect: (model: TargetModel) => void;
}

export const ModelSelector: React.FC<ModelSelectorProps> = ({ selectedModel, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center space-x-2 bg-surface hover:bg-zinc-800 text-zinc-300 font-medium py-2 px-3 rounded-md text-sm transition-colors border border-transparent hover:border-zinc-700"
      >
        <span className="text-secondary">Optimize for</span>
        <span className="text-white flex items-center gap-2">
           {selectedModel.name}
        </span>
        <ChevronDown size={14} className={`transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen && (
        <div className="absolute top-full left-0 mt-2 w-64 bg-surface border border-border rounded-lg shadow-xl z-50 overflow-hidden ring-1 ring-black ring-opacity-5">
          <div className="py-1">
            <div className="px-3 py-2 text-xs font-semibold text-zinc-500 uppercase tracking-wider">
              Select Target Model
            </div>
            {TARGET_MODELS.map((model) => (
              <button
                key={model.id}
                onClick={() => {
                  onSelect(model);
                  setIsOpen(false);
                }}
                className="w-full text-left px-4 py-3 flex items-start space-x-3 hover:bg-zinc-800 transition-colors group"
              >
                <div className={`mt-0.5 ${model.id === selectedModel.id ? 'opacity-100' : 'opacity-0 group-hover:opacity-50'}`}>
                  <Check size={16} className="text-emerald-500" />
                </div>
                <div>
                  <div className={`text-sm font-medium ${model.id === selectedModel.id ? 'text-white' : 'text-zinc-400 group-hover:text-zinc-200'}`}>
                    {model.name}
                  </div>
                  <div className="text-xs text-zinc-500 mt-0.5">
                    {model.description}
                  </div>
                </div>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, KeyboardEvent, useRef, useEffect } from 'react';
import { ArrowUp, Loader2 } from 'lucide-react';

interface FloatingInputProps {
  onSubmit: (text: string) => void;
  isLoading: boolean;
}

export const FloatingInput: React.FC<FloatingInputProps> = ({ onSubmit, isLoading }) => {
  const [text, setText] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleSubmit = () => {
    if (text.trim() && !isLoading) {
      onSubmit(text);
      setText(''); // Optional: clear after submit, or keep it? OpenAI clears it.
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto'; // Reset height
      }
    }
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 200)}px`;
    }
  }, [text]);

  return (
    <div className="w-full max-w-3xl mx-auto mb-6 px-4">
      <div className="relative bg-surface border border-zinc-700 rounded-2xl shadow-2xl overflow-hidden focus-within:ring-1 focus-within:ring-zinc-500 transition-all">
        <textarea
          ref={textareaRef}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Describe your use case, desired behavior, and issues..."
          className="w-full bg-transparent text-zinc-200 placeholder-zinc-500 px-4 py-4 pr-12 text-base resize-none focus:outline-none max-h-[200px] overflow-y-auto font-sans"
          rows={1}
          disabled={isLoading}
        />
        <div className="absolute right-2 bottom-2">
          <button
            onClick={handleSubmit}
            disabled={!text.trim() || isLoading}
            className={`p-2 rounded-xl flex items-center justify-center transition-all duration-200 ${
              text.trim() && !isLoading
                ? 'bg-white text-black hover:bg-zinc-200'
                : 'bg-zinc-800 text-zinc-500 cursor-not-allowed'
            }`}
          >
            {isLoading ? (
              <Loader2 size={18} className="animate-spin" />
            ) : (
              <ArrowUp size={18} strokeWidth={3} />
            )}
          </button>
        </div>
      </div>
      <div className="text-center mt-3">
         <p className="text-xs text-zinc-500">
           To apply <span className="underline decoration-zinc-700 cursor-pointer hover:text-zinc-400">best practices</span> for a specific model, select the model top-left and describe your intent.
         </p>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Copy, Check, Save } from 'lucide-react';

interface OutputAreaProps {
  prompt: string;
  explanation?: string;
  onChange: (text: string) => void;
  targetModelName: string;
}

export const OutputArea: React.FC<OutputAreaProps> = ({ prompt, explanation, onChange, targetModelName }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    await navigator.clipboard.writeText(prompt);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex flex-col h-full w-full max-w-5xl mx-auto pt-4 pb-4 px-4 sm:px-8">
      {/* Header Actions */}
      <div className="flex justify-between items-center mb-4">
        <div className="text-sm font-medium text-zinc-400">
          Developer message <span className="text-zinc-600 px-2">•</span> <span className="text-zinc-500">{targetModelName}</span>
        </div>
        <div className="flex space-x-2">
            <button 
                onClick={handleCopy}
                className="flex items-center space-x-2 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 px-3 py-1.5 rounded-md text-sm transition-colors"
            >
                {copied ? <Check size={14} /> : <Copy size={14} />}
                <span>{copied ? 'Copied' : 'Copy'}</span>
            </button>
             <button 
                className="flex items-center space-x-2 bg-transparent hover:bg-zinc-800 text-zinc-500 hover:text-zinc-300 px-3 py-1.5 rounded-md text-sm transition-colors"
            >
                <Save size={14} />
                <span>Save</span>
            </button>
        </div>
      </div>

      {/* Main Editor */}
      <div className="flex-grow relative bg-surface border border-zinc-800 rounded-lg overflow-hidden flex flex-col shadow-inner">
        {explanation && (
             <div className="bg-emerald-900/20 border-b border-emerald-900/50 px-4 py-2 text-xs text-emerald-400 font-mono">
                Running optimization: {explanation}
             </div>
        )}
        <textarea
          value={prompt}
          onChange={(e) => onChange(e.target.value)}
          className="w-full h-full bg-transparent p-6 text-zinc-200 font-mono text-sm sm:text-base resize-none focus:outline-none leading-relaxed"
          placeholder="Your optimized prompt will appear here..."
          spellCheck={false}
        />

        {!prompt && (
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <span className="text-zinc-700 text-sm">Waiting for input...</span>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { TARGET_MODELS } from './constants';
import { TargetModel } from './types';
import { ModelSelector } from './components/ModelSelector';
import { FloatingInput } from './components/FloatingInput';
import { OutputArea } from './components/OutputArea';
import { optimizePrompt } from './services/geminiService';
import { Sparkles, Terminal } from 'lucide-react';

export default function App() {
  const [selectedModel, setSelectedModel] = useState<TargetModel>(TARGET_MODELS[0]); // Default to Gemini
  const [optimizedPrompt, setOptimizedPrompt] = useState<string>('');
  const [explanation, setExplanation] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);

  const handleOptimization = async (inputPrompt: string) => {
    setIsLoading(true);
    setExplanation(''); // Clear previous explanation
    try {
      const result = await optimizePrompt(inputPrompt, selectedModel.id);
      setOptimizedPrompt(result.optimizedPrompt);
      setExplanation(result.explanation);
    } catch (error) {
      console.error(error);
      // In a real app, toast notification here
      setOptimizedPrompt(`Error: ${error instanceof Error ? error.message : 'Something went wrong.'}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-background text-zinc-100 overflow-hidden font-sans">

      {/* Top Navigation Bar */}
      <header className="h-14 border-b border-zinc-800/50 flex items-center justify-between px-4 sm:px-6 bg-background/50 backdrop-blur-md z-10 shrink-0">
        <div className="flex items-center space-x-4">
          <div className="flex items-center space-x-2 text-zinc-100 font-bold text-lg tracking-tight">
             <div className="bg-gradient-to-br from-emerald-500 to-cyan-500 w-8 h-8 rounded-lg flex items-center justify-center shadow-lg shadow-emerald-900/20">
                <Sparkles size={16} className="text-white fill-white" />
             </div>
             <span>Pr0mptim1zer</span>
          </div>
          <div className="h-4 w-px bg-zinc-700 mx-2 hidden sm:block"></div>
          <ModelSelector 
            selectedModel={selectedModel} 
            onSelect={setSelectedModel} 
          />
        </div>

        <div className="flex items-center space-x-4">
            <a href="#" className="text-zinc-500 hover:text-zinc-300 transition-colors hidden sm:block">
                <Terminal size={20} />
            </a>
            <div className="w-8 h-8 rounded-full bg-zinc-800 border border-zinc-700 flex items-center justify-center text-xs font-medium text-zinc-400">
                AI
            </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col relative overflow-hidden">

        {/* The Output/Editor Area fills the available space */}
        <div className="flex-grow overflow-y-auto">
            <OutputArea 
                prompt={optimizedPrompt} 
                explanation={explanation}
                onChange={setOptimizedPrompt}
                targetModelName={selectedModel.name}
            />
        </div>

        {/* The Input Bar sits at the bottom, above the fold */}
        <div className="shrink-0 w-full z-20 pb-4 pt-2 bg-gradient-to-t from-background via-background to-transparent">
            <FloatingInput 
                onSubmit={handleOptimization} 
                isLoading={isLoading} 
            />
        </div>
      </main>
    </div>
  );
}

