import React, { useState, useRef, useEffect, useMemo } from 'react';
import { ChevronDown, Check, MessageSquare, Code2 } from 'lucide-react';
import { TargetModel, ModelMode } from '../types';
import { TARGET_MODELS } from '../constants';

interface ModelSelectorProps {
  selectedModel: TargetModel;
  onSelect: (model: TargetModel) => void;
}

export const ModelSelector: React.FC<ModelSelectorProps> = ({ selectedModel, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [activeMode, setActiveMode] = useState<ModelMode>('chat');
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Group models by category within the active mode
  const groupedModels = useMemo<Record<string, TargetModel[]>>(() => {
    const groups: Record<string, TargetModel[]> = {};

    // Filter by mode first
    const filteredModels = TARGET_MODELS.filter(m => m.mode === activeMode);

    // Then group by provider
    filteredModels.forEach(model => {
      if (!groups[model.category]) {
        groups[model.category] = [];
      }
      groups[model.category].push(model);
    });
    return groups;
  }, [activeMode]);

  // Sync active mode if the selected model changes externally (though less likely in this flow)
  useEffect(() => {
    if (selectedModel) {
      setActiveMode(selectedModel.mode);
    }
  }, [selectedModel]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center space-x-2 bg-surface hover:bg-zinc-800 text-zinc-300 font-medium py-2 px-3 rounded-md text-sm transition-colors border border-transparent hover:border-zinc-700"
      >
        <span className="text-secondary hidden sm:inline">Optimize for</span>
        <span className="text-white flex items-center gap-2">
           {selectedModel.name}
        </span>
        <ChevronDown size={14} className={`transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen && (
        <div className="absolute top-full left-0 mt-2 w-80 max-h-[85vh] overflow-hidden flex flex-col bg-surface border border-border rounded-lg shadow-xl z-50 ring-1 ring-black ring-opacity-5">

          {/* Mode Switcher Tabs */}
          <div className="p-2 border-b border-border bg-zinc-900/50 backdrop-blur-sm grid grid-cols-2 gap-2">
            <button 
              onClick={() => setActiveMode('chat')}
              className={`flex items-center justify-center space-x-2 py-1.5 rounded text-xs font-semibold transition-all ${
                activeMode === 'chat' 
                  ? 'bg-zinc-700 text-white shadow-sm' 
                  : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800'
              }`}
            >
              <MessageSquare size={14} />
              <span>Chat Apps</span>
            </button>
            <button 
              onClick={() => setActiveMode('api')}
              className={`flex items-center justify-center space-x-2 py-1.5 rounded text-xs font-semibold transition-all ${
                activeMode === 'api' 
                  ? 'bg-zinc-700 text-white shadow-sm' 
                  : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800'
              }`}
            >
              <Code2 size={14} />
              <span>Developer APIs</span>
            </button>
          </div>

          {/* List Area */}
          <div className="overflow-y-auto flex-1">
            {Object.keys(groupedModels).length === 0 && (
                <div className="p-8 text-center text-zinc-500 text-sm">
                    No models found for this category.
                </div>
            )}

            {Object.entries(groupedModels).map(([category, models]) => (
              <div key={category} className="mb-2 last:mb-0">
                <div className="px-4 py-1.5 text-[10px] font-bold text-zinc-500 uppercase tracking-wider bg-zinc-900/30 sticky top-0 backdrop-blur-sm z-10">
                  {category}
                </div>
                {(models as TargetModel[]).map((model) => (
                  <button
                    key={model.id}
                    onClick={() => {
                      onSelect(model);
                      setIsOpen(false);
                    }}
                    className="w-full text-left px-4 py-2.5 flex items-start space-x-3 hover:bg-zinc-800 transition-colors group border-l-2 border-transparent hover:border-zinc-600"
                  >
                    <div className={`mt-0.5 ${model.id === selectedModel.id ? 'opacity-100' : 'opacity-0 group-hover:opacity-30'}`}>
                      <Check size={16} className="text-emerald-500" />
                    </div>
                    <div>
                      <div className={`text-sm font-medium ${model.id === selectedModel.id ? 'text-white' : 'text-zinc-400 group-hover:text-zinc-200'}`}>
                        {model.name}
                      </div>
                      <div className="text-[11px] text-zinc-500 mt-0.5 line-clamp-1">
                        {model.description}
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

